    "react": {
      "code": "// Stats Counter — via VengeanceUI (stats-counter) by Ashutoshx7, MIT License.\n// https://www.vengenceui.com/components/stats-counter\n\n// Simplified stand-in for the original `cn()` (clsx + tailwind-merge): joins\n// class names without tailwind-merge's conflicting-utility dedupe.\nfunction cn(...inputs) {\n  return inputs.flat(Infinity).filter(Boolean).join(\" \");\n}\nimport { useEffect, useRef, useState } from \"react\";\nimport { useInView, useMotionValue, useSpring } from \"framer-motion\";\nfunction StatsCounter({\n  value,\n  duration = 1.5,\n  prefix = \"\",\n  suffix = \"\",\n  decimals = 0,\n  className\n}) {\n  const ref = useRef(null);\n  const isInView = useInView(ref, {\n    once: true,\n    margin: \"-100px\"\n  });\n  const motionValue = useMotionValue(0);\n  const springValue = useSpring(motionValue, {\n    duration: duration * 1000,\n    bounce: 0\n  });\n  const [displayValue, setDisplayValue] = useState(0);\n  useEffect(() => {\n    if (isInView) {\n      motionValue.set(value);\n    }\n  }, [isInView, value, motionValue]);\n  useEffect(() => {\n    const unsubscribe = springValue.on(\"change\", latest => {\n      setDisplayValue(latest);\n    });\n    return unsubscribe;\n  }, [springValue]);\n  return <span ref={ref} className={cn(\"tabular-nums\", className)}>\n      {prefix}\n      {displayValue.toFixed(decimals)}\n      {suffix}\n    </span>;\n}\n\nexport default function Demo() {\n  return <StatsCounter value={12000} suffix=\"+\" duration={2} />;\n}\n",
      "css": "body {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 8%;\n  box-sizing: border-box;\n}"
    },
