    "react": {
      "code": "// Testimonials Card — via VengeanceUI (testimonials-card) by Ashutoshx7, MIT License.\n// https://www.vengenceui.com/components/testimonials-card\n\n// Simplified stand-in for the original `cn()` (clsx + tailwind-merge): joins\n// class names without tailwind-merge's conflicting-utility dedupe.\nfunction cn(...inputs) {\n  return inputs.flat(Infinity).filter(Boolean).join(\" \");\n}\nimport React, { useState, useMemo } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { ArrowLeft, ArrowRight } from \"lucide-react\";\nexport function TestimonialsCard({\n  items,\n  className,\n  width = 400,\n  showNavigation = true,\n  showCounter = true,\n  autoPlay = false,\n  autoPlayInterval = 3000\n}) {\n  const [activeIndex, setActiveIndex] = useState(0);\n  const [direction, setDirection] = useState(1);\n  const activeItem = items[activeIndex];\n\n  // Auto-play effect\n  React.useEffect(() => {\n    if (!autoPlay || items.length <= 1) return;\n    const interval = setInterval(() => {\n      setDirection(1);\n      setActiveIndex(prev => (prev + 1) % items.length);\n    }, autoPlayInterval);\n    return () => clearInterval(interval);\n  }, [autoPlay, autoPlayInterval, items.length]);\n  const handleNext = () => {\n    if (activeIndex < items.length - 1) {\n      setDirection(1);\n      setActiveIndex(activeIndex + 1);\n    }\n  };\n  const handlePrev = () => {\n    if (activeIndex > 0) {\n      setDirection(-1);\n      setActiveIndex(activeIndex - 1);\n    }\n  };\n\n  // Pre-calculate rotations for visual variety\n  const rotations = useMemo(() => [4, -2, -9, 7], []);\n  if (!items || items.length === 0) {\n    return null;\n  }\n  return <div className={cn(\"flex items-center justify-center p-8\", className)}>\n            <div className=\"relative grid  grid-cols-[1fr]  md:grid-cols-[1fr_1fr] md:grid-rows-[auto_auto_auto] gap-x-8 gap-y-2 w-full \" style={{\n      perspective: \"1400px\",\n      maxWidth: `${width}px`\n    }}>\n                {/* Counter */}\n                {showCounter && <div className=\"row-start-1 md:col-start-2 md:row-start-1 text-right font-mono text-sm text-neutral-500 dark:text-neutral-400\">\n                        {activeIndex + 1} / {items.length}\n                    </div>}\n\n                {/* Image Card Stack */}\n                <div className=\"row-start-2  col-start-1 md:row-start-1 row-span-3 relative w-full aspect-square\">\n                    <AnimatePresence custom={direction}>\n                        {items.map((item, index) => {\n            const isActive = index === activeIndex;\n            const offset = index - activeIndex;\n            return <motion.div key={item.id} className=\"absolute inset-0 w-full h-full overflow-hidden border-[6px] bg-neutral-200 dark:bg-neutral-800 border-white dark:border-neutral-700 shadow-2xl rounded-lg\" initial={{\n              x: offset * 15,\n              y: Math.abs(offset) * 6,\n              z: -150 * Math.abs(offset),\n              scale: 0.85 - Math.abs(offset) * 0.04,\n              rotateZ: rotations[index % 4],\n              opacity: isActive ? 1 : 0.5,\n              zIndex: 10 - Math.abs(offset)\n            }} animate={isActive ? {\n              x: [offset * 15, direction === 1 ? -200 : 200, 0],\n              y: [Math.abs(offset) * 6, 0, 0],\n              z: [-200, 150, 250],\n              scale: [0.85, 1.05, 1],\n              rotateZ: [rotations[index % 4], -5, 0],\n              opacity: 1,\n              zIndex: 100\n            } : {\n              x: offset * 15,\n              y: Math.abs(offset) * 6,\n              z: -150 * Math.abs(offset),\n              rotateZ: rotations[index % 4],\n              scale: 0.85 - Math.abs(offset) * 0.04,\n              opacity: 0.55,\n              zIndex: 10 - Math.abs(offset)\n            }} exit={{\n              x: direction === 1 ? -250 : 250,\n              z: -260,\n              scale: 0.75,\n              rotateZ: direction === 1 ? -10 : 10,\n              opacity: 0\n            }} transition={{\n              duration: 0.75,\n              ease: [0.22, 1, 0.36, 1]\n            }}>\n                                    <img src={item.image} alt={item.title} className=\"w-full h-full object-cover\" draggable={false} />\n                                </motion.div>;\n          })}\n                    </AnimatePresence>\n                </div>\n\n                {/* Text Area */}\n                <div className=\"col-start-1 md:col-start-2   md:row-start-1 flex flex-col justify-center min-h-[120px]\">\n                    <AnimatePresence mode=\"wait\">\n                        <motion.div key={activeItem.id} initial={{\n            opacity: 0,\n            y: 25\n          }} animate={{\n            opacity: 1,\n            y: 0\n          }} exit={{\n            opacity: 0,\n            y: -25\n          }} transition={{\n            duration: 0.35\n          }}>\n                            <h3 className=\"text-xl font-bold text-neutral-900 dark:text-white\">\n                                {activeItem.title}\n                            </h3>\n                            <p className=\"text-sm text-neutral-600 dark:text-neutral-400 mt-2\">\n                                {activeItem.description}\n                            </p>\n                        </motion.div>\n                    </AnimatePresence>\n                </div>\n\n                {/* Navigation Controls */}\n                {showNavigation && items.length > 1 && <div className=\"col-start-1 md:col-start-2 md:row-start-3 flex gap-2  m-auto -mt-2 md:mt-4  md:m-0\">\n                        <button disabled={activeIndex === 0} onClick={handlePrev} className={cn(\"flex items-center justify-center w-10 h-10 rounded-full border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-800 transition-all\", activeIndex === 0 ? \"opacity-50 cursor-not-allowed\" : \"hover:bg-neutral-100 dark:hover:bg-neutral-700 hover:scale-105\")} aria-label=\"Previous card\">\n                            <ArrowLeft className=\"w-4 h-4 text-neutral-700 dark:text-neutral-300\" />\n                        </button>\n                        <button disabled={activeIndex === items.length - 1} onClick={handleNext} className={cn(\"flex items-center justify-center w-10 h-10 rounded-full border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-800 transition-all\", activeIndex === items.length - 1 ? \"opacity-50 cursor-not-allowed\" : \"hover:bg-neutral-100 dark:hover:bg-neutral-700 hover:scale-105\")} aria-label=\"Next card\">\n                            <ArrowRight className=\"w-4 h-4 text-neutral-700 dark:text-neutral-300\" />\n                        </button>\n                    </div>}\n            </div>\n        </div>;\n}\n\nexport default function Demo() {\n  return <TestimonialsCard testimonials={[{\n    name: \"John Doe\",\n    text: \"Amazing product!\",\n    avatar: \"data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'160'%20height%3D'160'%3E%3Crect%20width%3D'160'%20height%3D'160'%20rx%3D'18'%20fill%3D'%23c9c9ce'%2F%3E%3Ccircle%20cx%3D'80'%20cy%3D'68'%20r%3D'26'%20fill%3D'%23fff'%20fill-opacity%3D'.55'%2F%3E%3Crect%20x%3D'34'%20y%3D'104'%20width%3D'92'%20height%3D'14'%20rx%3D'7'%20fill%3D'%23fff'%20fill-opacity%3D'.55'%2F%3E%3C%2Fsvg%3E\"\n  }]} />;\n}\n",
      "css": "body {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 8%;\n  box-sizing: border-box;\n}"
    },
    "credit": {
      "author": "Ashutoshx7",
      "url": "https://www.vengenceui.com/components/testimonials-card",
      "source": "VengeanceUI",
      "license": "MIT"
    }
