    "react": {
      "code": "// Kinetic Text Loader — via VengeanceUI (kinetic-text-loader) by Ashutoshx7, MIT License.\n// https://www.vengenceui.com/components/kinetic-text-loader\n\n// Simplified stand-in for the original `cn()` (clsx + tailwind-merge): joins\n// class names without tailwind-merge's conflicting-utility dedupe.\nfunction cn(...inputs) {\n  return inputs.flat(Infinity).filter(Boolean).join(\" \");\n}\nimport React from \"react\";\nexport function KineticTextLoader({\n  className,\n  text = \"Loading\",\n  ...props\n}) {\n  const letters = text.split(\"\");\n  return <div className={cn(\"relative flex items-center justify-center font-light\", className)} style={{\n    fontFamily: \"'Roboto', sans-serif\"\n  }} {...props}>\n      <style>{`\n        @import url('https://fonts.googleapis.com/css2?family=Roboto:wght@300&display=swap');\n        \n        @keyframes ktl-dotMove {\n          0%, 100% { transform: rotate(180deg) translate(-80px, -10px) rotate(-180deg); }\n          50% { transform: rotate(0deg) translate(-81px, 10px) rotate(0deg); }\n        }\n        @keyframes ktl-letterStretch {\n          0%, 100% { transform: scale(1, 0.35); transform-origin: 100% 75%; }\n          8%, 28% { transform: scale(1, 1.4); transform-origin: 100% 67%; }\n          37% { transform: scale(1, 0.875); transform-origin: 100% 75%; }\n          46% { transform: scale(1, 1.03); transform-origin: 100% 75%; }\n          50%, 97% { transform: scale(1); transform-origin: 100% 75%; }\n        }\n        @keyframes ktl-l-bounce {\n          0%, 45%, 70%, 100% { transform: scaleY(1.11); }\n          49% { transform: scaleY(0.31); }\n          50% { transform: scaleY(0.16); }\n          53% { transform: scaleY(0.63); }\n          60% { transform: scaleY(1.275); }\n          68% { transform: scaleY(1.04); }\n        }\n      `}</style>\n      \n      <div className=\"relative scale-75 md:scale-90 lg:scale-100\">\n        {/* The moving dot */}\n        <div className=\"absolute z-10 top-[40px] left-[85px] w-[6px] h-[6px] bg-neutral-800 dark:bg-neutral-200 rounded-full\" style={{\n        animation: \"ktl-dotMove 1800ms cubic-bezier(0.25,0.25,0.75,0.75) infinite\"\n      }} />\n        \n        <p className=\"relative m-0 whitespace-nowrap text-[3.75rem] text-neutral-800 dark:text-neutral-200\" aria-label={text}>\n          {letters.map((char, index) => {\n          if (index === 0 && char.toUpperCase() === 'L') {\n            return <span key={index} className=\"inline-block relative tracking-[8px] transform origin-[100%_70%]\" style={{\n              animation: \"ktl-l-bounce 1800ms cubic-bezier(0.25,0.25,0.75,0.75) infinite\"\n            }}>\n                  {char}\n                </span>;\n          }\n          if (index === 4 && char.toLowerCase() === 'i') {\n            return <span key={index} className=\"inline-block relative tracking-[8px] transform origin-[100%_70%]\" style={{\n              animation: \"ktl-letterStretch 1800ms cubic-bezier(0.25,0.23,0.73,0.75) infinite\"\n            }}>\n                  {char === 'i' ? 'ı' : char}\n                </span>;\n          }\n          return <span key={index} className=\"inline-block relative tracking-[8px]\">\n                {char}\n              </span>;\n        })}\n        </p>\n      </div>\n    </div>;\n}\n\nexport default function Demo() {\n  return <KineticTextLoader />;\n}\n",
      "css": "body {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 8%;\n  box-sizing: border-box;\n}"
    },
